<?php $items = $cartItems; ?>
<link rel="stylesheet" href="resources/css/products.css"><link rel="stylesheet" href="resources/css/cart.css"><link rel="stylesheet" href="resources/css/cart-grid.css">
<section class="sol-container products-page">
    <header class="products-hero"><span class="sol-badge sol-badge--emerald">Solaris · Giỏ hàng</span><h1>Sản phẩm đã chọn</h1><p>Kiểm tra số lượng rồi chuyển cấu hình sang khu vực Đề mô của member3.</p></header>
    <?php if (!$items): ?><div class="sol-glass-card products-empty">Giỏ hàng đang trống. <a href="index.php?page=products">Xem catalog sản phẩm</a></div><?php else: ?>
        <form method="post" class="sol-glass-card cart-table" id="cart-form"><input type="hidden" name="cart_action" value="demo_selected"><div class="cart-toolbar"><label><input type="checkbox" id="select-all"> Chọn tất cả</label><span id="selected-count">0 sản phẩm được chọn</span></div><div class="cart-row cart-head"><span></span><span>Sản phẩm</span><span>Đơn giá</span><span>Số lượng</span><span>Thành tiền</span><span></span></div><?php foreach ($items as $item): ?><div class="cart-row cart-item" data-price="<?= (float) $item['price'] ?>" data-id="<?= (int) $item['id'] ?>"><span><input class="cart-check" type="checkbox" name="selected[]" value="<?= (int) $item['id'] ?>"></span><span><strong><?= htmlspecialchars($item['name']) ?></strong><small><?= htmlspecialchars($item['product_code']) ?></small></span><span><?= number_format($item['price'], 0, ',', '.') ?> VNĐ</span><span><input class="products-input cart-quantity" type="number" name="quantity[<?= (int) $item['id'] ?>]" value="<?= (int) $item['quantity'] ?>" min="1" max="99"></span><span class="item-total"><?= number_format($item['price'] * $item['quantity'], 0, ',', '.') ?> VNĐ</span><span><button class="cart-remove" type="submit" name="cart_action" value="remove" formaction="index.php?page=cart" onclick="this.form.product_id.value='<?= (int) $item['id'] ?>'">Xóa</button></span></div><?php endforeach; ?><input type="hidden" name="product_id"><div class="cart-summary"><strong>Tổng đã chọn: <span id="selected-total">0 VNĐ</span></strong><button class="sol-btn sol-btn--secondary" type="submit" formaction="index.php?page=cart" name="cart_action" value="update">Cập nhật giỏ</button><button class="sol-btn sol-btn--solar" type="submit">Đề mô sản phẩm đã chọn →</button></div></form>
    <?php endif; ?>
</section>
<script>
(() => { const form = document.getElementById('cart-form'); if (!form) return; const all = document.getElementById('select-all'); const checks = [...form.querySelectorAll('.cart-check')]; const total = document.getElementById('selected-total'); const count = document.getElementById('selected-count'); const money = value => new Intl.NumberFormat('vi-VN').format(value) + ' VNĐ'; const refresh = () => { let sum = 0; let selected = 0; checks.forEach(check => { const row = check.closest('.cart-item'); const qty = Number(row.querySelector('.cart-quantity').value) || 1; row.querySelector('.item-total').textContent = money(Number(row.dataset.price) * qty); if (check.checked) { sum += Number(row.dataset.price) * qty; selected++; } }); total.textContent = money(sum); count.textContent = selected + ' sản phẩm được chọn'; all.checked = checks.length > 0 && selected === checks.length; }; all.addEventListener('change', () => { checks.forEach(check => { check.checked = all.checked; }); refresh(); }); checks.forEach(check => check.addEventListener('change', refresh)); form.querySelectorAll('.cart-quantity').forEach(input => input.addEventListener('input', refresh)); refresh(); })();
</script>
